@Override
    public Response service(Command command) {
        // MDC entries are copy-on-write maps in log4j2 — a put per command is a
        // full thread-context map copy per message. Put only when this thread's
        // tag actually changes and leave it sticky between commands (same
        // lifecycle-scoped pattern as the activemq.broker MDC entry), so the
        // steady-state per-command cost is a single allocation-free MDC.get.
        if (!connectorUriString.equals(MDC.get("activemq.connector"))) {
            MDC.put("activemq.connector", connectorUriString);
        }
        Response response = null;
        boolean responseRequired = command.isResponseRequired();
        int commandId = command.getCommandId();
        try {
            if (status.get() != PENDING_STOP) {
                response = command.visit(this);
            } else {
                response = new ExceptionResponse(transportException.get());
            }
        } catch (Throwable e) {
            if (SERVICELOG.isDebugEnabled() && e.getClass() != BrokerStoppedException.class) {
                SERVICELOG.debug("Error occurred while processing {} command: {}, exception: {}",
                        (responseRequired ? "sync" : "async"),
                        command,
                        e.getMessage(),
                        e);
            }

            if (e instanceof SuppressReplyException || (e.getCause() instanceof SuppressReplyException)) {
                LOG.info("Suppressing reply to: {} on: {}, cause: {}", command, e, e.getCause());
                responseRequired = false;
            }

            if (responseRequired) {
                if (e instanceof SecurityException || e.getCause() instanceof SecurityException) {
                    SERVICELOG.warn("Security Error occurred on connection to: {}, {}",
                            transport.getRemoteAddress(), e.getMessage());
                }
                response = new ExceptionResponse(e);
            } else {
                forceRollbackOnlyOnFailedAsyncTransactionOp(e, command);
                serviceException(e);
            }
        }
        if (responseRequired) {
            if (response == null) {
                response = new Response();
            }
            response.setCorrelationId(commandId);
        }
        // The context may have been flagged so that the response is not
        // sent.
        if (context != null) {
            if (context.isDontSendReponse()) {
                context.setDontSendReponse(false);
                response = null;
            }
            context = null;
        }
        return response;
    }

